<script lang="ts">
 import {onMount,onDestroy} from 'svelte';import {beforeNavigate} from '$app/navigation';
 import {api,message,dirtyEditor} from './workspace';import type {Draft} from './types';import ShareLinks from './ShareLinks.svelte';import InvitationSend from './InvitationSend.svelte';import SharePreviewFields from './SharePreviewFields.svelte';import ExperimentVisibility from './ExperimentVisibility.svelte';
 export let experiment:Draft;
 type Record={active?:boolean;document_id:string;revision_id?:string;purpose:string;title:string;body:string;description:string;image:string;url?:string;group_id?:string;members:{entity_id:string;name:string;joined_at:string}[];history:{id:string;resource_type:string;timestamp:string;actor:string;actor_name?:string}[];responses:{id:string;kind:string;name:string;body:string;created_at:string}[]};
 const labels:{[key:string]:string}={feedback:'Feedback',follow:'Follow along',collaboration:'Collaboration',advisor:'Advisor'};
 const wording:{[key:string]:string}={feedback:'How has this experiment affected you? Share feedback, a story, or an outcome you noticed.',follow:'Follow this experiment and see the learning as it unfolds.',collaboration:'Would you like to explore alongside me? Let’s share what we learn and support each other’s experiments.',advisor:'Would you be willing to offer advice and perspective as this experiment unfolds?'};
 let records:Record[]=[],draft:Record|null=null,baseline='',busy=false,loading=true,error='',uploading=false,version=0;
 $: dirty=!!draft&&JSON.stringify(draft)!==baseline;
 $: dirtyEditor.set(dirty);
 onDestroy(()=>dirtyEditor.set(false));
 beforeNavigate(({cancel})=>{if(dirty&&!confirm('Leave without saving this invitation?'))cancel();});
 function leave(){return !dirty||confirm('Discard unsaved invitation changes?');}
 function edit(record:Record){if(!leave())return;draft=structuredClone(record);baseline=JSON.stringify(draft);error='';}
 function create(){if(!leave())return;draft={document_id:crypto.randomUUID(),purpose:'feedback',title:`Feedback on ${experiment.title}`,body:wording.feedback,description:wording.feedback,image:'/api/shares/default-photo.jpg',members:[],history:[],responses:[]};baseline='';error='';}
 function purpose(){if(!draft)return;draft.title=`${labels[draft.purpose]}: ${experiment.title}`;draft.body=wording[draft.purpose];draft.description=wording[draft.purpose];}
 async function load(){loading=true;error='';try{const result=await api.call<{invitations:Record[]}>('invitation_definition_list',{id:experiment.revision.document_id});records=result?.invitations||[];}catch(e){error=message(e);}finally{loading=false;}}
 async function save(){if(!draft||busy)return;busy=true;error='';try{const id=draft.document_id;await api.call('invitation_definition_save',{id:experiment.revision.document_id},{document_id:id,expected_revision:draft.revision_id||null,purpose:draft.purpose,title:draft.title,body:draft.body,description:draft.description,image:draft.image});await load();const saved=records.find(r=>r.document_id===id);if(!saved)throw new Error('The saved invitation could not be loaded. Refresh before retrying.');draft=structuredClone(saved);baseline=JSON.stringify(draft);version++;}catch(e){error=message(e);}finally{busy=false;}}
 async function close(record:Record){if(!confirm('Close this invitation to new responses and members? Existing group memberships stay until you remove them.'))return;busy=true;error='';try{await api.call('invitation_close',{experiment:experiment.revision.document_id,group:record.group_id});if(draft?.document_id===record.document_id){draft=null;baseline='';}await load();}catch(e){error=message(e);}finally{busy=false;}}
 async function remove(record:Record,person:Record['members'][number]){if(!confirm(`Remove ${person.name} from this invitation’s ${labels[record.purpose]} group?`))return;busy=true;error='';try{await api.call('invitation_member_remove',{experiment:experiment.revision.document_id,group:record.group_id,person:person.entity_id});await load();if(draft?.document_id===record.document_id){draft=structuredClone(records.find(r=>r.document_id===record.document_id)!);baseline=JSON.stringify(draft);}}catch(e){error=message(e);}finally{busy=false;}}
 onMount(()=>{void load();});
</script>
<section class="panel"><div class="row between wrap"><div><h2>Invitations</h2><p>Each invitation has its own purpose, link, and role group.</p></div><button type="button" class="button primary" disabled={busy} on:click={create}>New invitation</button></div>
 {#if loading}<p role="status">Loading invitations…</p>{:else}{#each records as record (record.document_id)}<div class="panel"><span class="eyebrow">{labels[record.purpose]}{record.active===false?' · Closed':''}</span><h3>{record.title}</h3><p class="fine">{record.purpose==='feedback'?`${record.responses.length} responses · feedback does not add group members`:`${record.members.length} group members`}</p><button type="button" class="button secondary" disabled={busy||record.active===false} on:click={()=>edit(record)}>Edit invitation</button>{#if record.active!==false}<button type="button" class="text-button" disabled={busy||dirty} on:click={()=>close(record)}>Close invitation</button>{/if}</div>{:else}<p>Create a feedback, follow-along, collaboration, or advisor invitation. You can have several of each.</p>{/each}{/if}
 {#if draft}<form on:submit|preventDefault={save}><fieldset disabled={busy} style="border:0;padding:0;margin:0"><h3>{draft.revision_id?'Edit invitation':'New invitation'}</h3><label>Purpose<select bind:value={draft.purpose} on:change={purpose} disabled={!!draft.revision_id}><option value="feedback">Ask for feedback, stories, or outcomes</option><option value="follow">Invite someone to follow along</option><option value="collaboration">Invite collaboration</option><option value="advisor">Invite advice</option></select></label><p class="fine">Each invitation keeps its role. Create another invitation for a different role.</p><label>Invitation title<input bind:value={draft.title} required maxlength="180"/></label><label>Invitation text<textarea bind:value={draft.body} required rows="6" maxlength="100000"></textarea></label><SharePreviewFields title={draft.title} bind:description={draft.description} bind:image={draft.image} bind:uploading disabled={busy}/><p class="fine">Saving creates or updates a public invitation link with this text and photo. It doesn’t send email. Membership gives access only to viewer sections you select for this group; it never grants editing or ownership.</p><button class="button primary" disabled={busy||uploading||!draft.title.trim()||!draft.body.trim()||draft.description.trim().length<20}>{busy?'Saving…':draft.revision_id?'Save invitation & update link':'Save invitation & create link'}</button></fieldset></form><button type="button" class="text-button" on:click={()=>{if(leave()){draft=null;baseline='';}}}>Done editing</button>
 {#if draft?.url}<p class="fine">{dirty?'Save to update the shared text. The controls below use the last saved invitation.':''}</p>{#if !dirty}<ShareLinks url={draft.url} title={draft.title} description={draft.description} kind={draft.purpose}/>{#key draft.document_id}<InvitationSend documentId={draft.document_id} experimentId={experiment.revision.document_id} title={draft.title} description={draft.description} image={draft.image} kind={draft.purpose}/>{/key}{/if}{/if}{/if}
 {#if error}<p class="alert" role="alert">{error}</p>{/if}
</section>
<section class="panel"><div class="row between"><h2>People &amp; roles</h2><button type="button" class="text-button" disabled={busy||dirty} on:click={load}>Refresh people &amp; responses</button></div><p>You manage this experiment. Each invitation has a separate group; a person can belong to several groups.</p>
 {#each records as record (record.document_id)}<article class="panel"><span class="eyebrow">{labels[record.purpose]}{record.active===false?' · Closed':''}</span><h3>{record.title}</h3>{#if record.purpose==='feedback'}<p class="fine">Responding does not create membership.</p>{#each record.responses as response (response.id)}<div class="panel"><strong>{response.name||'Anonymous visitor'} · {response.kind}</strong><p class="fine">{response.created_at} UTC</p><p style="white-space:pre-wrap">{response.body}</p></div>{:else}<p class="fine">No feedback yet.</p>{/each}{:else}{#each record.members as person (person.entity_id)}<div class="row between wrap"><div><strong>{person.name}</strong><p class="fine">Joined {person.joined_at} UTC</p></div><button type="button" class="text-button" disabled={busy||dirty} on:click={()=>remove(record,person)}>Remove membership</button></div>{:else}<p class="fine">No members yet.</p>{/each}{/if}<details><summary>Membership &amp; invitation history</summary>{#each record.history as event (event.id)}<p>{event.resource_type.replaceAll('_',' ')} · {event.actor_name||'Experiment owner'} · {event.timestamp} UTC</p>{/each}</details></article>{:else}<p class="fine">Groups appear when you create an invitation.</p>{/each}
</section>
{#key experiment.revision.document_id+version}<ExperimentVisibility experimentId={experiment.revision.document_id}/>{/key}
